class FoodRatings { unordered_map<string,string> cuisines;unordered_map<string,int> ratings;unordered_map<string,set<pair<int,string>>> ranked;public:FoodRatings(vector<string>& foods,vector<string>& cuisineValues,vector<int>& ratingValues){for(int i=0;i<(int)foods.size();++i){cuisines[foods[i]]=cuisineValues[i];ratings[foods[i]]=ratingValues[i];ranked[cuisineValues[i]].insert({-ratingValues[i],foods[i]});}}void changeRating(string food,int newRating){string cuisine=cuisines[food];ranked[cuisine].erase({-ratings[food],food});ratings[food]=newRating;ranked[cuisine].insert({-newRating,food});}string highestRated(string cuisine){return ranked[cuisine].begin()->second;} };
